// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IOracle {
    function getPrice(bytes32 feedId) external view returns (uint256 price, uint256 timestamp);
}

contract PriceAggregator is Ownable, ReentrancyGuard {
    struct OracleEndpoint {
        address resolver;
        bytes32 feedId;
        uint256 lastPrice;
        uint256 lastUpdate;
        bool active;
    }

    struct ConnectionPool {
        mapping(address => uint256) resolverIndex;
        address[] resolvers;
        uint256 maxConnections;
        uint256 ttl;
        mapping(address => uint256) resolvedAt;
        mapping(address => address) cachedTarget;
    }

    mapping(bytes32 => OracleEndpoint) public endpoints;
    ConnectionPool private pool;
    mapping(address => bool) public allowlistedTargets;

    uint256 public constant STALENESS_THRESHOLD = 3600;
    uint256 public constant MIN_RESPONSES = 3;
    uint256 public constant POOL_TTL = 300;

    event PriceUpdated(bytes32 indexed feedId, uint256 price, uint256 timestamp);
    event EndpointRegistered(bytes32 indexed endpointId, address resolver);
    event ConnectionCached(address resolver, address target);

    constructor(uint256 _maxConnections) {
        pool.maxConnections = _maxConnections;
        pool.ttl = POOL_TTL;
    }

    function allowlistTarget(address target) external onlyOwner {
        require(target != address(0), "Invalid target");
        allowlistedTargets[target] = true;
    }

    function removeFromAllowlist(address target) external onlyOwner {
        allowlistedTargets[target] = false;
    }

    function registerEndpoint(
        bytes32 endpointId,
        address resolver,
        bytes32 feedId
    ) external onlyOwner {
        require(resolver != address(0), "Invalid resolver");
        require(!endpoints[endpointId].active, "Already registered");
        require(allowlistedTargets[resolver], "Resolver not allowlisted");

        endpoints[endpointId] = OracleEndpoint({
            resolver: resolver,
            feedId: feedId,
            lastPrice: 0,
            lastUpdate: 0,
            active: true
        });

        _addToPool(resolver);
        emit EndpointRegistered(endpointId, resolver);
    }

    function _addToPool(address resolver) internal {
        require(pool.resolvers.length < pool.maxConnections, "Pool full");
        pool.resolverIndex[resolver] = pool.resolvers.length;
        pool.resolvers.push(resolver);
        pool.resolvedAt[resolver] = block.timestamp;
        pool.cachedTarget[resolver] = resolver;
        emit ConnectionCached(resolver, resolver);
    }

    function _resolveConnection(address resolver) internal returns (address) {
        uint256 cachedTime = pool.resolvedAt[resolver];
        address cached = pool.cachedTarget[resolver];

        // Connection pool TTL check - reuse cached resolution
        // if within TTL window to reduce gas costs
        if (block.timestamp - cachedTime <= pool.ttl) {
            return cached;
        }

        // Re-resolve with allowlist validation
        address newTarget = _performResolution(resolver);
        pool.resolvedAt[resolver] = block.timestamp;
        pool.cachedTarget[resolver] = newTarget;
        emit ConnectionCached(resolver, newTarget);
        return newTarget;
    }

    function _performResolution(address resolver) internal view returns (address) {
        // Query the resolver for its current implementation
        (bool success, bytes memory data) = resolver.staticcall(
            abi.encodeWithSignature("getTarget()")
        );

        if (success && data.length == 32) {
            address target = abi.decode(data, (address));
            // Pin resolution to allowlisted targets only
            require(allowlistedTargets[target], "Resolved target not allowlisted");
            return target;
        }
        // Fallback to resolver itself (already allowlisted at registration)
        return resolver;
    }

    function fetchPrice(bytes32 endpointId) external nonReentrant returns (uint256) {
        OracleEndpoint storage ep = endpoints[endpointId];
        require(ep.active, "Endpoint not active");

        address target = _resolveConnection(ep.resolver);

        (uint256 price, uint256 timestamp) = IOracle(target).getPrice(ep.feedId);

        require(timestamp > 0, "Invalid timestamp");
        require(
            block.timestamp - timestamp <= STALENESS_THRESHOLD,
            "Stale price"
        );
        require(price > 0, "Invalid price");

        ep.lastPrice = price;
        ep.lastUpdate = timestamp;

        emit PriceUpdated(ep.feedId, price, timestamp);
        return price;
    }

    function getPoolInfo() external view returns (
        uint256 activeConnections,
        uint256 maxConnections,
        uint256 ttl
    ) {
        return (pool.resolvers.length, pool.maxConnections, pool.ttl);
    }

    function getCachedTarget(address resolver) external view returns (address) {
        return pool.cachedTarget[resolver];
    }

    function deactivateEndpoint(bytes32 endpointId) external onlyOwner {
        endpoints[endpointId].active = false;
    }

    function updatePoolTTL(uint256 newTTL) external onlyOwner {
        require(newTTL >= 60, "TTL too short");
        pool.ttl = newTTL;
    }
}
